import sys, subprocess, re
from markdown_it import MarkdownIt
md = MarkdownIt("commonmark").enable("table")
def leftovers(text):
    out=[]
    tokens = md.parse(text)
    for t in tokens:
        if t.type=="inline":
            for c in t.children:
                if c.type=="text" and "**" in c.content:
                    out.append((t.map[0]+1 if t.map else 0, c.content.strip()[:80]))
    return out
rng_base, rng_head = sys.argv[1], sys.argv[2]
files = subprocess.check_output(["git","diff","--name-only",rng_base,rng_head,"--","*.md"]).decode().split()
for f in files:
    b = subprocess.run(["git","show",f"{rng_base}:{f}"],capture_output=True).stdout.decode()
    h = subprocess.check_output(["git","show",f"{rng_head}:{f}"]).decode()
    lb, lh = leftovers(b), leftovers(h)
    if len(lh) != len(lb) or lh:
        print(f, "base:",len(lb),"head:",len(lh))
        for x in lh: print("   H", x)
        for x in lb: print("   B", x)
EOF
